from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    freq = parts[0]
    k = int(parts[1])
    res = []

    if freq == "DAILY":
        d = s
        while len(res) < count:
            res.append(d.isoformat())
            d += timedelta(days=k)

    elif freq == "WEEKLY":
        days = {t: i for i, t in enumerate(["MO", "TU", "WE", "TH", "FR", "SA", "SU"])}
        wd = {days[t] for t in parts[3].split(",")}
        week0 = (s - timedelta(days=s.weekday())).toordinal() // 7
        # candidate week index w >= week0, w % k == 0; w index = week0 - i for integer
        # find smallest multiple of k >= week0
        w = ((week0 + k - 1) // k) * k
        while len(res) < count:
            week_start = date.fromordinal((w - week0) * 7 + (s - timedelta(days=s.weekday())).toordinal())
            for offset in range(7):
                d = week_start + timedelta(days=offset)
                if d.weekday() in wd and d >= s:
                    res.append(d.isoformat())
                    if len(res) == count:
                        break
            w += k

    elif freq == "MONTHLY" and len(parts) == 4:
        dspec = parts[3]
        m0 = s.year * 12 + s.month - 1
        i = (m0 + k - 1) // k * k - m0  # not quite; simpler below
        # active months: m0 + k*j for j>=0
        j = 0
        y, m = s.year, s.month
        while len(res) < count:
            if j % k == 0:
                if dspec == "-1":
                    last = calendar.monthrange(y, m)[1]
                    d = date(y, m, last)
                else:
                    day = int(dspec)
                    if day <= calendar.monthrange(y, m)[1]:
                        d = date(y, m, day)
                    else:
                        d = None
                if d is not None and d >= s:
                    res.append(d.isoformat())
            j += 1
            m += 1
            if m == 13:
                m = 1
                y += 1

    elif freq == "MONTHLY":
        n = int(parts[3])
        wdcode = parts[4]
        wd = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}[wdcode]
        j = 0
        y, m = s.year, s.month
        while len(res) < count:
            if j % k == 0:
                first = date(y, m, 1)
                days = [d for d in range(1, calendar.monthrange(y, m)[1] + 1)
                        if date(y, m, d).weekday() == wd]
                if days:
                    d = date(y, m, days[n - 1] if n > 0 else days[n])
                    if d >= s:
                        res.append(d.isoformat())
            j += 1
            m += 1
            if m == 13:
                m = 1
                y += 1

    elif freq == "YEARLY":
        mm, dd = map(int, parts[3].split("-"))
        y = s.year
        j = 0
        while len(res) < count:
            yy = y + j * k
            try:
                d = date(yy, mm, dd)
                if d >= s:
                    res.append(d.isoformat())
            except ValueError:
                pass
            j += 1

    return res
